#!/usr/bin/env bash
set -Eeuo pipefail;IFS=$'\n\t';umask 077
D="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")"&&pwd -P)";M="$D/model.py";F="$D/fixtures/cases.json";U="$(id -u)";R="/tmp/reliability-atlas-les0045-model-$U"
die(){ printf 'lab=fail reason=%s\n' "$*" >&2;exit 1;};doctor(){ ((U>0))||die root;grep -Eq '^ID="?ubuntu"?$' /etc/os-release||die ubuntu;grep -Eq '^VERSION_ID="?24\.04' /etc/os-release||die version;python3 -c 'import pathlib,sys;compile(pathlib.Path(sys.argv[1]).read_text(),sys.argv[1],"exec")' "$M";printf 'doctor=pass runtime=kubernetes-security-model-only\n';};need(){ doctor>/dev/null;[[ -d "$R"&&! -L "$R" ]]||die state;python3 "$M" verify "$R">/dev/null;};setup(){ doctor;[[ ! -e "$R"&&! -L "$R" ]]||die exists;mkdir -m 0700 "$R";cp "$F" "$R/cases.json";printf 'les0045:%s\n' "$U">"$R/.les0045-sentinel";chmod 0600 "$R"/* "$R/.les0045-sentinel";python3 "$M" init "$R";};all(){ need;for c in expired-token missing-binding wildcard-overgrant token-automount secret-metadata pod-security-deny webhook-timeout tenant-escape;do python3 "$M" diagnose "$R" "$c">/dev/null;done;python3 "$M" verify "$R";};cleanup(){ need;rm -rf -- "$R";[[ ! -e "$R" ]]||die remains;printf 'cleanup=pass state_absent=true\n';}
case "${1:-}" in doctor)doctor;;setup)setup;;list)need;python3 "$M" list "$R";;diagnose)need;python3 "$M" diagnose "$R" "${2:-}";;diagnose-as)need;python3 "$M" diagnose "$R" "${2:-}" --answer "${3:-}";;verify-cases)all;;inject-unknown)need;printf x>"$R/unexpected";;clear-unknown)rm -f "$R/unexpected";need;;cleanup)cleanup;;*)exit 2;;esac
